/// <summary>
/// Extension of GUPItemBasePriceCalcDialog
/// </summary>
[ExtensionOf(formStr(GUPItemBasePriceCalcDialog))]
internal final class METGUPItemBasePriceCalcDialogFrm_Extension
{
}

Method.Source:
    /// <summary>
    /// GeneratePriceChangeInquiry
    /// </summary>
    /// <param name = "_set">set</param>
    /// <param name = "_generatePriceChangeInquiry">GeneratePriceChangeInquiry</param>
    /// <returns>NoYesValue</returns>
    edit NoYes metGeneratePriceChangeInquiry(
        boolean                     _set,
        NoYes  _generatePriceChangeInquiry)
    {
        if (_set)
        {
            calcJob.parmGeneratePriceChangeInquiry(_generatePriceChangeInquiry);
            calcJobAll.parmGeneratePriceChangeInquiry(_generatePriceChangeInquiry);
        }

        return calcJob.parmGeneratePriceChangeInquiry();

    }

    /// <summary>
    /// Include claim from vendor parm
    /// </summary>
    /// <param name = "_set">set</param>
    /// <param name = "_includeClaimFromVendor">Include claim from vendor</param>
    /// <returns>NoYesValue</returns>
    edit NoYes metIncludeClaimFromVendor(boolean    _set,
                                        NoYes       _includeClaimFromVendor)
    {
        if (_set)
        {
            calcJob.parmMETIncludeClaimFromVendor(_includeClaimFromVendor);
            calcJobAll.parmMETIncludeClaimFromVendor(_includeClaimFromVendor);
        }

        return calcJob.parmMETIncludeClaimFromVendor();
    }
